import { chromium } from "playwright-core";
import { pathToFileURL } from "node:url";
import http from "node:http";
import fs from "node:fs";
import path from "node:path";

const root = "/Users/sinchunyeung/.treehouse/simplification-of-trajectory-streams-bec452/3/simplification-of-trajectory-streams/web";
const usability = path.join(root, "usability");
const chrome = "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome";

function mime(filePath) {
  if (filePath.endsWith(".js")) return "text/javascript";
  if (filePath.endsWith(".html")) return "text/html";
  if (filePath.endsWith(".css")) return "text/css";
  if (filePath.endsWith(".png")) return "image/png";
  return "application/octet-stream";
}

const server = http.createServer((req, res) => {
  const url = new URL(req.url, "http://127.0.0.1");
  if (url.pathname === "/api/traces") {
    res.writeHead(200, { "Content-Type": "application/json" });
    res.end(JSON.stringify({ traces: [] }));
    return;
  }
  const filePath = url.pathname === "/"
    ? path.join(root, "index.html")
    : path.join(root, url.pathname.replace(/^\//, ""));
  fs.readFile(filePath, (err, data) => {
    if (err) {
      res.writeHead(404);
      res.end("not found");
      return;
    }
    res.writeHead(200, { "Content-Type": mime(filePath) });
    res.end(data);
  });
});

await new Promise((resolve) => server.listen(0, "127.0.0.1", resolve));
const port = server.address().port;
const origin = `http://127.0.0.1:${port}`;

const browser = await chromium.launch({
  executablePath: chrome,
  headless: true,
});

try {
  const fixture = await browser.newPage({ viewport: { width: 430, height: 1100 } });
  await fixture.goto(pathToFileURL(path.join(usability, "mobile-instructions-shortcuts.html")).href, {
    waitUntil: "domcontentloaded",
  });
  await fixture.screenshot({
    path: path.join(usability, "mobile-instructions-shortcuts.png"),
    fullPage: true,
  });

  const live = await browser.newPage({
    viewport: { width: 390, height: 844 },
    deviceScaleFactor: 2,
    isMobile: true,
    hasTouch: true,
  });
  await live.goto(origin + "/", { waitUntil: "domcontentloaded" });
  await live.addStyleTag({
    content: "html, body { overflow: auto !important; }",
  });
  await live.evaluate(() => {
    document.body.classList.add("trace-loaded-mobile", "playback-ready");
    const sidebar = document.getElementById("sidebar");
    const hud = document.getElementById("traceLoadingHud");
    const drop = document.getElementById("dropHint");
    const dock = document.getElementById("mobileTransport");
    if (sidebar) sidebar.style.display = "flex";
    if (hud) hud.classList.remove("visible");
    if (drop) drop.style.display = "none";
    if (dock) {
      dock.classList.add("visible");
      dock.setAttribute("aria-hidden", "false");
    }
    document.getElementById("statusIndices").innerHTML = `
      <div class="status-idx-block">
        <span class="idx-label">p (start)</span>
        <span class="idx-num">#0</span>
      </div>
      <div class="status-idx-block">
        <span class="idx-label">v_i (current)</span>
        <span class="idx-num">#1</span>
      </div>`;
    document.getElementById("statusGrid").innerHTML = `
      <span>step</span><span><b>1</b></span>
      <span>alive</span><span><b>1 / 1</b></span>`;
    document.getElementById("paramsBar").innerHTML = `
      <span class="params-metric params-metric--blue params-metric--frechet">
        <span class="params-metric-body">
          <span class="params-metric-label">Computed Fréchet distance</span>
          <span class="params-metric-value"><b>0.1842</b></span>
        </span>
      </span>
      <span class="params-metric params-metric--blue params-metric--time">
        <span class="params-metric-body">
          <span class="params-metric-label">Simplification time</span>
          <span class="params-metric-value"><b>42.1800 ms</b></span>
        </span>
      </span>`;
  });
  await live.locator("#sidebar .section").last().scrollIntoViewIfNeeded();
  await live.waitForTimeout(200);
  const liveMetrics = await live.evaluate(() => {
    const card = document.querySelector("#sidebar .section:last-of-type");
    const table = card.querySelector(".mobile-shortcuts");
    const desktop = card.querySelector(".desktop-shortcuts");
    const rows = [...table.querySelectorAll("td:first-child")].map((td) => td.textContent.trim());
    const style = getComputedStyle(table);
    const deskStyle = getComputedStyle(desktop);
    return {
      innerWidth: window.innerWidth,
      mobileDisplay: style.display,
      desktopDisplay: deskStyle.display,
      rows,
      hasKbd: table.querySelectorAll("kbd").length,
      desktopHasKbd: desktop.querySelectorAll("kbd").length,
      cardText: card.innerText,
    };
  });
  console.log(JSON.stringify(liveMetrics, null, 2));
  await live.screenshot({
    path: path.join(usability, "mobile-instructions-shortcuts-live.png"),
    fullPage: false,
  });

  const desktop = await browser.newPage({ viewport: { width: 1280, height: 800 } });
  await desktop.goto(origin + "/", { waitUntil: "domcontentloaded" });
  const desktopMetrics = await desktop.evaluate(() => {
    const mobile = document.querySelector(".mobile-shortcuts");
    const desk = document.querySelector(".desktop-shortcuts");
    return {
      innerWidth: window.innerWidth,
      mobileDisplay: getComputedStyle(mobile).display,
      desktopDisplay: getComputedStyle(desk).display,
      desktopRows: [...desk.querySelectorAll("td:first-child")].map((td) => td.textContent.trim()),
    };
  });
  console.log("desktop", JSON.stringify(desktopMetrics, null, 2));
} finally {
  await browser.close();
  server.close();
}
